"use client";

import { useEffect, useId, useRef, useState } from "react";

import { PlusIcon, RefreshIcon } from "@/components/blocks/parts/icons";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { AddPanel, type NewVariable } from "./env-variables/add-panel";
import { CompareTable } from "./env-variables/compare-table";
import { ENVS, type Env, INITIAL_VARIABLES, type ParsedLine, type Variable } from "./env-variables/data";
import { Fold } from "./env-variables/fold";
import { ImportPanel } from "./env-variables/import-panel";
import { VariableRow } from "./env-variables/variable-row";
import { InfoIcon, LoaderIcon, UploadIcon } from "./icons";
import { SearchField } from "./search-field";

type View = "variables" | "compare";
type Panel = "add" | "import" | null;

const VIEWS: { value: View; label: string }[] = [
  { value: "variables", label: "Variables" },
  { value: "compare", label: "Compare" },
];

const ALL_ENVS = ENVS.map((env) => env.id);

/**
 * Environment variables for one project: search the keys, reveal, copy or
 * edit a value, switch each key on per environment, import a pasted `.env`
 * file, and compare environments by fingerprint. A banner asks for a
 * redeploy once a change is waiting.
 */
export function EnvVariables({ className }: { className?: string }) {
  const [variables, setVariables] = useState<Variable[]>(INITIAL_VARIABLES);
  const [view, setView] = useState<View>("variables");
  const [panel, setPanel] = useState<Panel>(null);
  const [query, setQuery] = useState("");
  const [pending, setPending] = useState(0);
  const [deploying, setDeploying] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const addRef = useRef<HTMLButtonElement>(null);
  const importRef = useRef<HTMLButtonElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const titleId = useId();

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  const changed = (message: string) => {
    setPending((count) => count + 1);
    setAnnouncement(message);
  };

  const closePanel = () => {
    const opener = panel === "add" ? addRef : importRef;
    setPanel(null);
    requestAnimationFrame(() => opener.current?.focus());
  };

  const toggleEnv = (key: string, env: Env) => {
    const variable = variables.find((item) => item.key === key);
    if (!variable) return;
    const values = { ...variable.values };
    const label = ENVS.find((item) => item.id === env)?.label ?? env;
    if (values[env] === undefined) {
      values[env] = variable.values.production ?? variable.values.preview ?? variable.values.development ?? "";
      changed(`${key} turned on in ${label}.`);
    } else {
      delete values[env];
      changed(`${key} turned off in ${label}.`);
    }
    setVariables((current) => current.map((item) => (item.key === key ? { ...item, values, updatedBy: "You", updated: "just now" } : item)));
  };

  const saveValue = (key: string, value: string) => {
    setVariables((current) =>
      current.map((item) =>
        item.key === key
          ? { ...item, values: Object.fromEntries(Object.keys(item.values).map((env) => [env, value])), updatedBy: "You", updated: "just now" }
          : item,
      ),
    );
    changed(`${key} saved.`);
  };

  const add = ({ key, value, sensitive, envs }: NewVariable) => {
    const values = Object.fromEntries(envs.map((env) => [env, value]));
    setVariables((current) => [{ key, sensitive, updatedBy: "You", updated: "just now", values }, ...current]);
    setPanel(null);
    changed(`${key} added.`);
    requestAnimationFrame(() => addRef.current?.focus());
  };

  const importLines = (lines: ParsedLine[]) => {
    setVariables((current) => {
      const next = [...current];
      for (const line of lines) {
        const values = Object.fromEntries(ALL_ENVS.map((env) => [env, line.value]));
        const fresh: Variable = { key: line.key, sensitive: false, updatedBy: "You", updated: "just now", values };
        const at = next.findIndex((item) => item.key === line.key);
        if (at === -1) next.unshift(fresh);
        else next[at] = { ...fresh, sensitive: next[at]?.sensitive ?? false };
      }
      return next;
    });
    setPanel(null);
    changed(`${lines.length} keys imported.`);
    requestAnimationFrame(() => importRef.current?.focus());
  };

  const redeploy = () => {
    if (deploying) return;
    setDeploying(true);
    setAnnouncement("Redeploying production.");
    timer.current = setTimeout(() => {
      setDeploying(false);
      setPending(0);
      setAnnouncement("Redeployed. Every change is live.");
    }, 1600);
  };

  const needle = query.trim().toUpperCase();
  const shown = variables.filter((variable) => variable.key.includes(needle));

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Environment variables
          </h2>
          <p className="text-sm text-muted-foreground">
            <span className="font-mono">booking-api</span>, {variables.length} keys in {ENVS.length} environments
          </p>
        </div>
        <div className="flex gap-2">
          <Button ref={importRef} variant="outline" aria-expanded={panel === "import"} onClick={() => setPanel(panel === "import" ? null : "import")}>
            <UploadIcon aria-hidden="true" className="size-4" />
            Import .env
          </Button>
          <Button ref={addRef} aria-expanded={panel === "add"} onClick={() => setPanel(panel === "add" ? null : "add")}>
            <PlusIcon aria-hidden="true" className="size-4" />
            Add variable
          </Button>
        </div>
      </header>

      <Fold open={pending > 0} className="relative flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-3">
        <span aria-hidden="true" className="pointer-events-none absolute inset-0 bg-marketing-amber-surface opacity-70" />
        <p className="relative flex items-center gap-2 text-sm">
          <InfoIcon aria-hidden="true" className="size-4 shrink-0 text-marketing-amber-ink" />
          {pending} {pending === 1 ? "change takes" : "changes take"} effect after the next redeploy.
        </p>
        <Button size="sm" className="relative" onClick={redeploy} aria-disabled={deploying}>
          {deploying ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : <RefreshIcon aria-hidden="true" className="size-4" />}
          {deploying ? "Redeploying" : "Redeploy"}
        </Button>
      </Fold>

      <Fold open={panel === "add"} className="border-b border-border">
        <AddPanel existing={variables.map((item) => item.key)} onAdd={add} onClose={closePanel} />
      </Fold>
      <Fold open={panel === "import"} className="border-b border-border">
        <ImportPanel existing={variables.map((item) => item.key)} onImport={importLines} onClose={closePanel} />
      </Fold>

      <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4">
        <SearchField label="Search keys" value={query} onChange={setQuery} code className="w-full @lg:w-64" />
        <SegmentedControl aria-label="View" options={VIEWS} value={view} onValueChange={setView} />
      </div>

      {shown.length === 0 ? (
        <p className="px-5 py-10 text-center text-sm text-muted-foreground">No key matches “{query.trim()}”.</p>
      ) : view === "variables" ? (
        <ul aria-label="Keys" className="flex flex-col py-2">
          {shown.map((variable) => (
            <li key={variable.key}>
              <VariableRow
                variable={variable}
                onToggle={(env) => toggleEnv(variable.key, env)}
                onSave={(value) => saveValue(variable.key, value)}
              />
            </li>
          ))}
        </ul>
      ) : (
        <CompareTable variables={shown} />
      )}
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

