import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type FormEvent, type KeyboardEvent, useCallback, useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";

import { ENVS, type Env, isValidKey } from "./data";
import { EnvToggle } from "./env-toggle";

/** What a person filled in to add a key. */
export interface NewVariable {
  key: string;
  value: string;
  sensitive: boolean;
  envs: Env[];
}

/** Props for the panel that adds one key. */
export interface AddPanelProps {
  existing: string[];
  onAdd: (variable: NewVariable) => void;
  onClose: () => void;
}

/** A form for one new key: its name, value, whether it is sensitive, and where it is set. */
export function AddPanel({ existing, onAdd, onClose }: AddPanelProps) {
  const [key, setKey] = useState("");
  const [value, setValue] = useState("");
  const [sensitive, setSensitive] = useState(false);
  const [envs, setEnvs] = useState<Env[]>(["development", "preview", "production"]);
  const [tried, setTried] = useState(false);
  const keyId = useId();
  const valueId = useId();
  const errorId = useId();
  const focusOnOpen = useCallback((node: HTMLInputElement | null) => node?.focus(), []);

  const name = key.trim();
  const error = !isValidKey(name)
    ? "Use capitals, digits and underscores, such as CLINIC_TIMEZONE."
    : existing.includes(name)
      ? `${name} already exists. Edit it in the list instead.`
      : value.trim() === ""
        ? "Add a value."
        : envs.length === 0
          ? "Turn on at least one environment."
          : null;

  const submit = (event: FormEvent) => {
    event.preventDefault();
    setTried(true);
    if (error) return;
    onAdd({ key: name, value: value.trim(), sensitive, envs });
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    onClose();
  };

  return (
    <form onSubmit={submit} onKeyDown={onKeyDown} noValidate aria-label="Add variable" className="flex flex-col gap-3 px-5 py-4">
      <div className="grid gap-3 @2xl:grid-cols-2">
        <div className="flex flex-col gap-1.5">
          <label htmlFor={keyId} className="text-sm font-medium">
            Key
          </label>
          <Input
            id={keyId}
            ref={focusOnOpen}
            value={key}
            onChange={(event) => setKey(event.target.value.toUpperCase().replace(/\s/g, "_"))}
            placeholder="CLINIC_TIMEZONE"
            autoComplete="off"
            spellCheck={false}
            aria-invalid={tried && error !== null}
            aria-describedby={tried && error ? errorId : undefined}
          />
        </div>
        <div className="flex flex-col gap-1.5">
          <label htmlFor={valueId} className="text-sm font-medium">
            Value
          </label>
          <Input
            id={valueId}
            value={value}
            onChange={(event) => setValue(event.target.value)}
            placeholder="Europe/Dublin"
            autoComplete="off"
            spellCheck={false}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
        <label className="flex cursor-pointer items-center gap-2 text-sm">
          <Checkbox checked={sensitive} onCheckedChange={(checked) => setSensitive(checked === true)} />
          Sensitive, write-only after saving
        </label>
        <div role="group" aria-label="Environments" className="flex gap-0.5">
          {ENVS.map((env) => (
            <EnvToggle
              key={env.id}
              label={env.label}
              short={env.short}
              keyName="The new key"
              on={envs.includes(env.id)}
              onToggle={() => setEnvs((current) => (current.includes(env.id) ? current.filter((id) => id !== env.id) : [...current, env.id]))}
            />
          ))}
        </div>
      </div>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p id={errorId} role="alert" className="text-sm text-marketing-orange-ink">
          {tried ? error : null}
        </p>
        <div className="flex gap-2">
          <Button type="button" variant="ghost" onClick={onClose}>
            Cancel
          </Button>
          <Button type="submit">Add variable</Button>
        </div>
      </div>
    </form>
  );
}

/** The three places a project runs. */
export type Env = "development" | "preview" | "production";

/** The environments in column order, with a short label for a narrow toggle. */
export const ENVS: { id: Env; label: string; short: string }[] = [
  { id: "development", label: "Development", short: "Dev" },
  { id: "preview", label: "Preview", short: "Prev" },
  { id: "production", label: "Production", short: "Prod" },
];

/** One key and its value in each environment it is set in. */
export interface Variable {
  key: string;
  /** A sensitive value is write-only: once saved, nobody can read it back. */
  sensitive: boolean;
  updatedBy: string;
  updated: string;
  values: Partial<Record<Env, string>>;
}

/** The sample project's keys. Every value is a made-up placeholder. */
export const INITIAL_VARIABLES: Variable[] = [
  {
    key: "DATABASE_URL",
    sensitive: true,
    updatedBy: "Priya Natarajan",
    updated: "3 days ago",
    values: { development: "db.fernhill.test/app-dev", preview: "db.fernhill.test/app-preview", production: "db.fernhill.test/app" },
  },
  {
    key: "BOOKING_PAGE_URL",
    sensitive: false,
    updatedBy: "Tom Okafor",
    updated: "2 weeks ago",
    values: { development: "http://localhost:3000/book", preview: "https://preview.fernhill.test/book", production: "https://book.fernhill.test" },
  },
  {
    key: "REMINDER_HOURS_BEFORE",
    sensitive: false,
    updatedBy: "Ana Ruiz",
    updated: "1 month ago",
    values: { development: "24", preview: "24", production: "24" },
  },
  {
    key: "SMS_SENDER_KEY",
    sensitive: true,
    updatedBy: "Priya Natarajan",
    updated: "5 days ago",
    values: { preview: "sms_test_demo_0000", production: "sms_live_demo_7f21" },
  },
  {
    key: "SLOT_LENGTH_MINUTES",
    sensitive: false,
    updatedBy: "Tom Okafor",
    updated: "yesterday",
    values: { development: "15", preview: "20", production: "20" },
  },
  {
    key: "FEATURE_WAITLIST",
    sensitive: false,
    updatedBy: "Ana Ruiz",
    updated: "4 hours ago",
    values: { development: "true", preview: "true" },
  },
];

/** A key name the platform accepts: capitals, digits and underscores, not starting with a digit. */
export const isValidKey = (key: string) => /^[A-Z_][A-Z0-9_]*$/.test(key);

/** The value a row shows: production first, then preview, then development. */
export const shownValue = (variable: Variable) =>
  variable.values.production ?? variable.values.preview ?? variable.values.development ?? "";

/** A short, stable fingerprint of a value, so two environments can be compared without showing either. */
export function fingerprint(value: string): string {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0").slice(0, 6);
}

/** One line of a pasted file, read as a key and value, with a reason when it cannot be imported. */
export interface ParsedLine {
  key: string;
  value: string;
  problem: "invalid" | "duplicate" | "exists" | null;
}

/** Reads a pasted `.env` file. Comments and blank lines are skipped; quotes around a value are removed. */
export function parseEnvFile(text: string, existing: string[]): ParsedLine[] {
  const seen = new Set<string>();
  const lines: ParsedLine[] = [];
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;
    const equals = line.indexOf("=");
    const key = (equals === -1 ? line : line.slice(0, equals)).replace(/^export\s+/, "").trim();
    const value = equals === -1 ? "" : line.slice(equals + 1).trim().replace(/^(["'])(.*)\1$/, "$2");
    const problem = !isValidKey(key) ? "invalid" : seen.has(key) ? "duplicate" : existing.includes(key) ? "exists" : null;
    seen.add(key);
    lines.push({ key, value, problem });
  }
  return lines;
}

/** A sample file for the import box, with one bad name and one repeat to show the warnings. */
export const SAMPLE_ENV_FILE = `# Copied from the clinic's old server
CHECKIN_KIOSK_PIN_LENGTH=4
MAX_BOOKINGS_PER_DAY=40
max-waitlist=12
MAX_BOOKINGS_PER_DAY=45
SLOT_LENGTH_MINUTES=30`;

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** Props for one environment's on and off toggle on a key. */
export interface EnvToggleProps {
  label: string;
  short: string;
  keyName: string;
  on: boolean;
  onToggle: () => void;
}

/**
 * A small toggle that sets a key in one environment. When it turns on, its
 * box fills with a short scale and its check draws in.
 */
export function EnvToggle({ label, short, keyName, on, onToggle }: EnvToggleProps) {
  const reduceMotion = useReducedMotion();
  return (
    <Button
      variant="ghost"
      size="sm"
      aria-pressed={on}
      aria-label={`${keyName} in ${label}`}
      title={label}
      onClick={onToggle}
    >
      <motion.span
        aria-hidden="true"
        initial={false}
        animate={{ scale: on && !reduceMotion ? [0.8, 1.08, 1] : 1 }}
        transition={{ duration: 0.22 }}
        className={cn(
          "flex size-4 items-center justify-center rounded-sm border motion-safe:transition-colors",
          on ? "border-chart-2 bg-chart-2 text-background" : "border-muted-foreground/50",
        )}
      >
        <svg viewBox="0 0 12 12" className="size-3" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <motion.path
            d="M2.5 6.2 5 8.5l4.5-5"
            initial={false}
            animate={{ pathLength: on ? 1 : 0, opacity: on ? 1 : 0 }}
            transition={{ duration: reduceMotion ? 0 : 0.2, delay: on && !reduceMotion ? 0.06 : 0 }}
          />
        </svg>
      </motion.span>
      <span className={cn("text-xs", on ? "text-foreground" : "text-muted-foreground")}>{short}</span>
    </Button>
  );
}

import { AlertTriangleIcon } from "@/components/blocks/parts/icons";
import { Table, TableBody, TableHead, TableHeader, TableRow, TableCell } from "@/components/ui/table";
import { cn } from "@/lib/utils";

import { ENVS, type Variable, fingerprint } from "./data";

const HUES = ["text-chart-1", "text-chart-2", "text-chart-3"];

/**
 * Compares each key across the three environments by a short fingerprint of
 * its value, so differences show without revealing any value. Matching
 * fingerprints share a colour; a key that differs is flagged.
 */
export function CompareTable({ variables }: { variables: Variable[] }) {
  return (
    <div className="px-2 py-2">
      <Table className="min-w-128">
        <caption className="sr-only">Value fingerprints by environment</caption>
        <TableHeader>
          <TableRow>
            <TableHead scope="col">
              Key
            </TableHead>
            {ENVS.map((env) => (
              <TableHead key={env.id} scope="col">
                {env.label}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {variables.map((variable) => {
            const prints = ENVS.map((env) => {
              const value = variable.values[env.id];
              return value === undefined ? null : fingerprint(value);
            });
            const distinct = [...new Set(prints.filter((print): print is string => print !== null))];
            const differs = distinct.length > 1 || prints.includes(null);
            return (
              <TableRow key={variable.key}>
                <TableHead scope="row">
                  <span className="flex items-center gap-1.5 font-mono text-xs font-medium">
                    {variable.key}
                    {differs ? (
                      <span className="flex items-center gap-1 font-sans font-normal text-marketing-amber-ink">
                        <AlertTriangleIcon aria-hidden="true" className="size-3.5" />
                        Differs
                      </span>
                    ) : null}
                  </span>
                </TableHead>
                {prints.map((print, index) => (
                  <TableCell key={ENVS[index]?.id}>
                    {print === null ? (
                      <span className="text-xs text-muted-foreground">Not set</span>
                    ) : (
                      <code
                        className={cn(
                          "rounded-md border border-current px-1.5 py-0.5 font-mono text-xs",
                          HUES[distinct.indexOf(print) % HUES.length],
                        )}
                      >
                        {print}
                      </code>
                    )}
                  </TableCell>
                ))}
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

/** Props for a panel that opens and closes in place. */
export interface FoldProps {
  open: boolean;
  children: ReactNode;
  className?: string;
  id?: string;
}

/**
 * Opens a panel with its height and opacity, and closes it with a quicker
 * ease. With reduced motion it appears and disappears at once.
 */
export function Fold({ open, children, className, id }: FoldProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {open ? (
        <motion.div
          id={id}
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1, transition: { duration: reduceMotion ? 0 : 0.26, ease: [0.22, 1, 0.36, 1] } }}
          exit={{ height: 0, opacity: 0, transition: { duration: reduceMotion ? 0 : 0.15, ease: [0.4, 0, 1, 1] } }}
          className="overflow-hidden"
        >
          <div className={className}>{children}</div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

