import { type KeyboardEvent, useCallback, useId, useState } from "react";

import { AlertTriangleIcon, CircleCheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { type ParsedLine, SAMPLE_ENV_FILE, parseEnvFile } from "./data";

/** Props for the box that imports a pasted `.env` file. */
export interface ImportPanelProps {
  existing: string[];
  onImport: (lines: ParsedLine[]) => void;
  onClose: () => void;
}

const PROBLEM_TEXT = {
  invalid: "Not a valid name. Use capitals, digits and underscores.",
  duplicate: "Appears twice. The first one is kept.",
  exists: "Already set. The new value replaces it.",
} satisfies Record<NonNullable<ParsedLine["problem"]>, string>;

/**
 * Takes a pasted `.env` file and lists each key it found, with a warning on a
 * bad name, a repeat, or a key that already exists, before anything is saved.
 */
export function ImportPanel({ existing, onImport, onClose }: ImportPanelProps) {
  const [text, setText] = useState(SAMPLE_ENV_FILE);
  const fieldId = useId();
  const focusOnOpen = useCallback((node: HTMLTextAreaElement | null) => node?.focus(), []);
  const lines = parseEnvFile(text, existing);
  const importable = lines.filter((line) => line.problem === null || line.problem === "exists");

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    onClose();
  };

  return (
    <div onKeyDown={onKeyDown} className="grid gap-4 px-5 py-4 @2xl:grid-cols-2">
      <div className="flex flex-col gap-1.5">
        <label htmlFor={fieldId} className="text-sm font-medium">
          Paste a .env file
        </label>
        <div className="font-mono">
          <Textarea
            id={fieldId}
            ref={focusOnOpen}
            value={text}
            onChange={(event) => setText(event.target.value)}
            rows={7}
            spellCheck={false}
            className="min-h-40 resize-y"
          />
        </div>
      </div>
      <div className="flex min-w-0 flex-col gap-2">
        <h3 className="text-sm font-medium">
          {importable.length} of {lines.length} keys ready
        </h3>
        <ul aria-live="polite" className="flex max-h-44 scroll-fade-effect-y scrollbar-none flex-col gap-1.5 overflow-y-auto text-xs">
          {lines.map((line, index) => {
            const ok = line.problem === null || line.problem === "exists";
            return (
              <li key={`${line.key}-${index}`} className="flex items-start gap-2">
                {ok ? (
                  <CircleCheckIcon aria-hidden="true" className="mt-px size-3.5 shrink-0 text-marketing-green-ink" />
                ) : (
                  <AlertTriangleIcon aria-hidden="true" className="mt-px size-3.5 shrink-0 text-marketing-amber-ink" />
                )}
                <span className="min-w-0">
                  <span className={cn("font-mono", !ok && "line-through")}>{line.key || "(no name)"}</span>
                  {line.problem ? <span className="block text-muted-foreground">{PROBLEM_TEXT[line.problem]}</span> : null}
                </span>
              </li>
            );
          })}
        </ul>
        <div className="mt-auto flex justify-end gap-2 pt-2">
          <Button variant="ghost" onClick={onClose}>
            Cancel
          </Button>
          <Button disabled={importable.length === 0} onClick={() => onImport(importable)}>
            Import {importable.length} {importable.length === 1 ? "key" : "keys"}
          </Button>
        </div>
      </div>
    </div>
  );
}

