import { type FormEvent, type KeyboardEvent, useCallback, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { CopyIconButton } from "../copy-icon-button";
import { EyeIcon, EyeOffIcon, LockIcon, PencilIcon } from "../icons";
import { ENVS, type Env, type Variable, shownValue } from "./data";
import { EnvToggle } from "./env-toggle";
import { Fold } from "./fold";

/** Props for one key in the variables view. */
export interface VariableRowProps {
  variable: Variable;
  onToggle: (env: Env) => void;
  onSave: (value: string) => void;
}

const MASK = "••••••••••••";

/**
 * One key: who changed it last, its value masked with reveal and copy, an
 * inline editor, and a toggle per environment. A sensitive value is
 * write-only, so it has no reveal and no copy.
 */
export function VariableRow({ variable, onToggle, onSave }: VariableRowProps) {
  const [revealed, setRevealed] = useState(false);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const editRef = useRef<HTMLButtonElement>(null);
  const inputId = useId();
  const panelId = useId();
  const value = shownValue(variable);
  const focusOnOpen = useCallback((node: HTMLInputElement | null) => node?.focus(), []);

  const close = () => {
    setEditing(false);
    requestAnimationFrame(() => editRef.current?.focus());
  };

  const save = (event: FormEvent) => {
    event.preventDefault();
    if (draft.trim() === "") return;
    onSave(draft.trim());
    close();
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    close();
  };

  return (
    <div className="group relative px-3 py-1">
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-2 inset-y-0.5 rounded-xl bg-muted opacity-0 motion-safe:transition-opacity group-hover:opacity-60"
      />
      <div className="relative grid gap-x-4 gap-y-2 px-2 py-2.5 @2xl:grid-cols-[14rem_1fr_auto] @2xl:items-center">
        <div className="min-w-0">
          <h3 className="flex items-center gap-1.5 truncate font-mono text-sm font-medium">
            {variable.key}
            {variable.sensitive ? (
              <span title="Sensitive, write-only" className="text-marketing-amber-ink">
                <LockIcon aria-hidden="true" className="size-3.5" />
                <span className="sr-only">, sensitive, write-only</span>
              </span>
            ) : null}
          </h3>
          <p className="truncate text-xs text-muted-foreground">
            {variable.updatedBy}, {variable.updated}
          </p>
        </div>
        <div className="flex min-w-0 items-center gap-1">
          <code className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground">
            {variable.sensitive ? "Write-only value" : revealed ? value : MASK}
          </code>
          {variable.sensitive ? null : (
            <>
              <Button
                variant="ghost"
                size="icon"
                aria-pressed={revealed}
                aria-label={`${revealed ? "Hide" : "Reveal"} ${variable.key}`}
                onClick={() => setRevealed(!revealed)}
              >
                {revealed ? <EyeOffIcon aria-hidden="true" className="size-4" /> : <EyeIcon aria-hidden="true" className="size-4" />}
              </Button>
              <CopyIconButton value={value} label={`Copy ${variable.key}`} />
            </>
          )}
          <Button
            ref={editRef}
            variant="ghost"
            size="icon"
            aria-expanded={editing}
            aria-controls={panelId}
            aria-label={`Edit ${variable.key}`}
            onClick={() => {
              setDraft(variable.sensitive ? "" : value);
              setEditing(!editing);
            }}
          >
            <PencilIcon aria-hidden="true" className="size-4" />
          </Button>
        </div>
        <div role="group" aria-label={`Environments for ${variable.key}`} className="flex gap-0.5">
          {ENVS.map((env) => (
            <EnvToggle
              key={env.id}
              label={env.label}
              short={env.short}
              keyName={variable.key}
              on={variable.values[env.id] !== undefined}
              onToggle={() => onToggle(env.id)}
            />
          ))}
        </div>
      </div>
      <Fold open={editing} id={panelId} className="relative px-2 pb-3">
        <form onSubmit={save} onKeyDown={onKeyDown} className="flex flex-wrap items-end gap-2">
          <div className="flex min-w-0 flex-1 flex-col gap-1">
            <label htmlFor={inputId} className="text-xs text-muted-foreground">
              {variable.sensitive ? "New value. The old one stays hidden." : "Value in every environment it is set in"}
            </label>
            <Input
              id={inputId}
              ref={focusOnOpen}
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
              autoComplete="off"
              spellCheck={false}
            />
          </div>
          <Button type="button" variant="ghost" onClick={close}>
            Cancel
          </Button>
          <Button type="submit" disabled={draft.trim() === ""}>
            Save
          </Button>
        </form>
      </Fold>
    </div>
  );
}

